# Adaptive rejection sampler for bounded log-concave densities.
# Based on Gilks and Wild (1992).

.validate_domain <- function(domain) {
  if (!is.numeric(domain) || length(domain) != 2L || anyNA(domain) ||
      any(!is.finite(domain)) || domain[1] >= domain[2])
    stop("domain must contain two finite increasing numbers")
  as.numeric(domain)
}

.log_density <- function(f, x) {
  value <- tryCatch(f(x), error = function(e)
    stop("density_function failed: ", conditionMessage(e)))
  if (!is.numeric(value) || length(value) != length(x))
    stop("density_function must return a numeric vector of matching length")
  if (anyNA(value) || any(is.nan(value)) || any(value < 0))
    stop("density_function returned NA, NaN, or negative values")
  if (any(!is.finite(value)))
    stop("density_function must return finite values")
  ifelse(value > 0, log(value), -Inf)
}

.check_log_concavity <- function(f, domain, grid = 61L, tolerance = 1e-7) {
  x <- seq(domain[1], domain[2], length.out = grid)
  y <- .log_density(f, x)
  if (any(!is.finite(y)))
    stop("density must be positive throughout the supplied domain")
  second_difference <- y[-c(1L, 2L)] - 2 * y[-c(1L, length(y))] +
    y[-c(length(y) - 1L, length(y))]
  if (any(second_difference > tolerance * (1 + max(abs(y)))))
    stop("density appears to be non-log-concave")
  invisible(TRUE)
}

.make_hull <- function(x, y, slope, domain) {
  m <- length(x)
  z <- c(domain[1], rep(NA_real_, m - 1L), domain[2])
  if (m > 1L) {
    for (i in seq_len(m - 1L)) {
      den <- slope[i] - slope[i + 1L]
      z[i + 1L] <- if (abs(den) < 1e-12) {
        (x[i] + x[i + 1L]) / 2
      } else {
        (y[i + 1L] - slope[i + 1L] * x[i + 1L] -
           y[i] + slope[i] * x[i]) / den
      }
    }
  }
  if (any(!is.finite(z)) || any(diff(z) <= 0))
    stop("could not construct a valid tangent envelope")
  list(x = x, y = y, slope = slope, intercept = y - slope * x, z = z)
}

.exp_integral <- function(a, b, lo, hi) {
  if (abs(a) < 1e-10) exp(b) * (hi - lo)
  else exp(b) * (exp(a * hi) - exp(a * lo)) / a
}

.sample_envelope <- function(h, n) {
  k <- length(h$x)
  mass <- vapply(seq_len(k), function(i)
    .exp_integral(h$slope[i], h$intercept[i], h$z[i], h$z[i + 1L]),
    numeric(1))
  if (any(!is.finite(mass)) || sum(mass) <= 0)
    stop("invalid envelope mass")
  probabilities <- mass / sum(mass)
  pieces <- sample.int(k, n, replace = TRUE, prob = probabilities)
  u <- runif(n)
  result <- numeric(n)
  for (j in seq_len(n)) {
    i <- pieces[j]
    lo <- h$z[i]
    hi <- h$z[i + 1L]
    a <- h$slope[i]
    if (abs(a) < 1e-10) result[j] <- lo + u[j] * (hi - lo)
    else {
      left <- exp(a * lo)
      right <- exp(a * hi)
      result[j] <- log(left + u[j] * (right - left)) / a
    }
  }
  result
}

.slopes_from_points <- function(x, y) {
  secant <- diff(y) / diff(x)
  # Secant slopes are decreasing for a concave log-density.
  slope <- c(secant[1L],
             if (length(secant) > 1L)
               (secant[-length(secant)] + secant[-1L]) / 2 else numeric(0),
             secant[length(secant)])
  if (any(diff(slope) > 1e-8))
    stop("non-log-concavity detected while updating the envelope")
  slope
}

# Generate n samples from a bounded, log-concave target density.
ars <- function(density_function, domain, n = sample_count) {
  if (!is.function(density_function))
    stop("density_function must be a function")
  domain <- .validate_domain(domain)
  if (missing(n)) stop("n must be supplied")
  if (length(n) != 1L || !is.numeric(n) || is.na(n) ||
      !is.finite(n) || n < 0 || n != as.integer(n))
    stop("n must be a non-negative integer")
  n <- as.integer(n)
  if (n == 0L) return(numeric(0))

  .check_log_concavity(density_function, domain)
  initial <- domain[1] + diff(domain) * c(.15, .35, .65, .85)
  x <- initial
  y <- .log_density(density_function, x)
  slope <- .slopes_from_points(x, y)
  accepted <- numeric(0)
  attempts <- 0L
  limit <- max(10000L, 200L * n)

  while (length(accepted) < n && attempts < limit) {
    hull <- .make_hull(x, y, slope, domain)
    batch <- min(256L, n - length(accepted))
    proposal <- .sample_envelope(hull, batch)
    lp <- .log_density(density_function, proposal)
    piece <- pmin(length(x), pmax(1L,
      findInterval(proposal, hull$z, rightmost.closed = TRUE)))
    upper <- hull$slope[piece] * proposal + hull$intercept[piece]
    if (any(lp > upper + 1e-7))
      stop("non-log-concave density detected during sampling")
    keep <- log(runif(batch)) <= lp - upper
    accepted <- c(accepted, proposal[keep])
    attempts <- attempts + batch

    # Add rejected points to adapt the envelope.
    add <- sort(unique(proposal[!keep]))
    add <- add[add > domain[1] & add < domain[2]]
    if (length(add)) {
      x <- sort(c(x, add))
      y <- .log_density(density_function, x)
      slope <- .slopes_from_points(x, y)
    }
  }
  if (length(accepted) < n)
    stop("sampling did not converge; check log-concavity and domain")
  accepted[seq_len(n)]
}

# Formal tests against known moments and invalid-input behavior.
test <- function() {
  set.seed(12345)
  normal <- ars(function(x) dnorm(x), c(-8, 8), n = 4000)
  write.table(normal, "/app/normal_samples.txt", row.names = FALSE,
              col.names = FALSE)
  normal_ok <- abs(mean(normal)) < 0.08 && abs(sd(normal) - 1) < 0.08
  cat(sprintf("NORMAL_MOMENTS: %s (mean=%.4f, sd=%.4f)\n",
      if (normal_ok) "PASS" else "FAIL", mean(normal), sd(normal)))

  set.seed(12346)
  exponential <- ars(function(x) dexp(x), c(0, 12), n = 3000)
  exponential_ok <- abs(mean(exponential) - 1) < 0.08 &&
    abs(sd(exponential) - 1) < 0.08
  cat(sprintf("EXPONENTIAL_MOMENTS: %s (mean=%.4f, sd=%.4f)\n",
      if (exponential_ok) "PASS" else "FAIL", mean(exponential), sd(exponential)))

  invalid_ok <- tryCatch({
    ars(function(x) dnorm(x), c(1, 1), n = 2)
    FALSE
  }, error = function(e) TRUE)
  cat(sprintf("INPUT_VALIDATION: %s\n", if (invalid_ok) "PASS" else "FAIL"))

  nonconcave_ok <- tryCatch({
    ars(function(x) 0.5 * dnorm(x, -1, .15) +
          0.5 * dnorm(x, 1, .15), c(-3, 3), n = 20)
    FALSE
  }, error = function(e) TRUE)
  cat(sprintf("NON_LOG_CONCAVE_CHECK: %s\n",
      if (nonconcave_ok) "PASS" else "FAIL"))

  invisible(all(normal_ok, exponential_ok, invalid_ok, nonconcave_ok))
}

