# Adaptive rejection sampling for finite-domain log-concave densities.

.validate_domain <- function(domain) {
  if (!is.numeric(domain) || length(domain) != 2L || anyNA(domain) ||
      any(!is.finite(domain)) || domain[1] >= domain[2])
