  as.numeric(domain)
}

.log_density <- function(f, x) {
  value <- tryCatch(f(x), error = function(e)
    stop("density_function failed: ", conditionMessage(e)))
  if (!is.numeric(value) || length(value) != length(x) || anyNA(value) ||
      any(is.nan(value)) || any(value < 0) || any(!is.finite(value)))
    stop("density_function must return finite nonnegative numeric values")
  ifelse(value > 0, log(value), -Inf)
}

.check_log_concavity <- function(f, domain, grid = 81L, tolerance = 1e-7) {
  x <- seq(domain[1], domain[2], length.out = grid)
  y <- .log_density(f, x)
  if (any(!is.finite(y))) stop("density must be positive throughout domain")
  second <- diff(y, differences = 2)
  if (any(second > tolerance * (1 + max(abs(y)))))
    stop("density appears to be non-log-concave")
  invisible(TRUE)
}

.slopes_from_points <- function(x, y) {
  secant <- diff(y) / diff(x)
  slope <- c(secant[1L],
    if (length(secant) > 1L)
      (secant[-length(secant)] + secant[-1L]) / 2 else numeric(0),
    secant[length(secant)])
  if (any(diff(slope) > 1e-7))
    stop("non-log-concavity detected while updating hull")
  slope
}

.make_hull <- function(x, y, slope, domain) {
  z <- c(domain[1], rep(NA_real_, length(x) - 1L), domain[2])
  if (length(x) > 1L) for (i in seq_len(length(x) - 1L)) {
    den <- slope[i] - slope[i + 1L]
    z[i + 1L] <- if (abs(den) < 1e-12) (x[i] + x[i + 1L]) / 2 else
      (y[i + 1L] - slope[i + 1L] * x[i + 1L] - y[i] + slope[i] * x[i]) / den
  }
  if (any(!is.finite(z)) || any(diff(z) <= 0))
    stop("could not construct a valid tangent hull")
  list(slope = slope, intercept = y - slope * x, z = z)
}

.exp_integral <- function(a, b, lo, hi) {
  if (abs(a) < 1e-10) exp(b) * (hi - lo)
  else exp(b) * (exp(a * hi) - exp(a * lo)) / a
}

.sample_envelope <- function(h, n) {
  k <- length(h$slope)
  mass <- vapply(seq_len(k), function(i)
    .exp_integral(h$slope[i], h$intercept[i], h$z[i], h$z[i + 1L]), numeric(1))
  if (any(!is.finite(mass)) || sum(mass) <= 0) stop("invalid envelope")
  piece <- sample.int(k, n, replace = TRUE, prob = mass)
  u <- runif(n); result <- numeric(n)
  for (j in seq_len(n)) {
    i <- piece[j]; a <- h$slope[i]; lo <- h$z[i]; hi <- h$z[i + 1L]
    result[j] <- if (abs(a) < 1e-10) lo + u[j] * (hi - lo) else
      log(exp(a * lo) + u[j] * (exp(a * hi) - exp(a * lo))) / a
  }
  result
}

