  if (!is.function(density_function)) stop("density_function must be a function")
  domain <- .validate_domain(domain)
  if (missing(n) || length(n) != 1L || !is.numeric(n) || is.na(n) ||
      !is.finite(n) || n < 0 || n != as.integer(n))
    stop("n must be a non-negative integer")
  n <- as.integer(n)
  if (n == 0L) return(numeric(0))
  .check_log_concavity(density_function, domain)

  x <- domain[1] + diff(domain) * c(.15, .35, .65, .85)
  y <- .log_density(density_function, x)
  slope <- .slopes_from_points(x, y)
  result <- numeric(0); attempts <- 0L
  max_attempts <- max(10000L, 200L * n)

  while (length(result) < n && attempts < max_attempts) {
    h <- .make_hull(x, y, slope, domain)
    batch <- min(256L, n - length(result))
    proposal <- .sample_envelope(h, batch)
    lp <- .log_density(density_function, proposal)
    index <- pmin(length(x), pmax(1L,
      findInterval(proposal, h$z, rightmost.closed = TRUE)))
    upper <- h$slope[index] * proposal + h$intercept[index]
    if (any(lp > upper + 1e-7))
      stop("non-log-concave density detected during sampling")
    keep <- log(runif(batch)) <= lp - upper
    result <- c(result, proposal[keep]); attempts <- attempts + batch

    rejected <- sort(unique(proposal[!keep]))
    rejected <- rejected[rejected > domain[1] & rejected < domain[2]]
    if (length(rejected)) {
      x <- sort(c(x, rejected))
      y <- .log_density(density_function, x)
      slope <- .slopes_from_points(x, y)
    }
  }
  if (length(result) < n) stop("sampling failed to converge")
  result[seq_len(n)]
